-- Тема 07: уточнения по проверке Codex (36 исправлений в 17 вопросах), ключи не меняются.
-- Источник: scripts/questions/071_codex_topic07_fixes.js
-- Повторный запуск безопасен: вопрос и вариант ищутся по тексту, прежнее или уже новое значение допустимо,
-- иначе пакет отменяется. Ключи ответов, число и порядок вариантов не меняются.

BEGIN;
SET LOCAL standard_conforming_strings = on;
LOCK TABLE questions IN SHARE ROW EXCLUSIVE MODE;

DO $fix$
DECLARE fix record; matches integer; qid integer; k text;
BEGIN
    FOR fix IN SELECT * FROM (VALUES
        ('question', 'Чем рискует асинхронный режим фиксации?', NULL, NULL, NULL, 'Включён асинхронный режим фиксации (synchronous_commit = off), остальные настройки по умолчанию. Чем рискует такой режим?'),
        ('question', 'Какие обычные транзакции после восстановления после сбоя считаются оборванными?', NULL, NULL, NULL, 'Какие транзакции, изменявшие журналируемые данные, не будут считаться зафиксированными после аварийного восстановления? Двухфазная фиксация не используется.'),
        ('option', 'Какую страницу выбирает алгоритм вытеснения из буферного кеша?', 'Ту, к которой реже всего обращались', 'Редко используемую в последнее время', 'Алгоритм по счётчику обращений приближённо выбирает страницы, которые в последнее время использовались реже других.', 'Алгоритм по счётчику использования приближённо выбирает страницы, которые в последнее время использовались реже других.'),
        ('option', 'Какую страницу выбирает алгоритм вытеснения из буферного кеша?', 'Ту, что дольше всех не менялась', NULL, 'Изменения страницы для выбора не важны: учитывается частота обращений.', 'Давность изменения не является критерием выбора: учитываются счётчик использования и закрепление буфера; грязную выбранную страницу перед заменой записывают.'),
        ('option', 'В чём главное правило журнала предзаписи (WAL)?', 'Журнал попадает на диск раньше изменённых данных', 'Записи WAL сохраняются раньше соответствующих данных', 'Журнальная запись попадает на диск раньше изменённых ею данных, поэтому после сбоя изменения можно восстановить по журналу.', NULL),
        ('option', 'Что делает контрольная точка?', 'Сбрасывает на диск все грязные буферы', 'Сбрасывает накопленные изменения на диск', 'Сбрасывает на диск все буферы, грязные на начало контрольной точки, и ограничивает объём журнала для восстановления: после неё восстановление начинается с этой точки.', 'Контрольная точка сохраняет на диске изменения, накопленные к её началу (более поздние могут остаться в кеше), и ограничивает объём журнала для восстановления: после неё восстановление начинается с этой точки.'),
        ('option', 'Чем процесс bgwriter отличается от checkpointer?', 'Записывает журнал предзаписи на диск вместо walwriter', NULL, 'Журнал пишет walwriter.', 'Журнал пишет walwriter; WAL также могут сбрасывать обслуживающие процессы.'),
        ('option', 'Чем процесс bgwriter отличается от checkpointer?', 'Пишет грязные буферы, которые скоро будут вытеснены', 'Заранее записывает буферы — кандидатов на вытеснение', 'bgwriter пишет только часть грязных буферов — те, что скоро будут вытеснены, чтобы у них уже была записанная копия.', 'bgwriter пишет часть грязных буферов — вероятных кандидатов на вытеснение, чтобы у них уже была записанная копия.'),
        ('option', 'Что верно для контрольной точки?', 'Выполняется по команде администратора, а не по расписанию', NULL, 'Выполняется периодически: по времени и по объёму журнала, а также при остановке сервера и по команде CHECKPOINT.', 'Выполняется периодически: по времени и по объёму журнала, а также при остановке сервера; ручная команда CHECKPOINT тоже существует.'),
        ('option', 'Что верно для контрольной точки?', 'Сбрасывает все грязные буферы, включая буферы clog', 'Сбрасывает данные и статусы транзакций', 'Записываются все буферы, грязные на начало контрольной точки, в том числе служебные.', 'Сохраняются изменения данных и служебное состояние, в том числе статусы транзакций (pg_xact, исторически clog), накопленные к началу контрольной точки.'),
        ('option', 'Что верно для контрольной точки?', 'Запись буферов растягивается во времени', 'Плановая запись обычно растягивается во времени', 'У плановых контрольных точек запись распределяется во времени согласно checkpoint_completion_target.', 'У плановых контрольных точек запись распределяется во времени согласно checkpoint_completion_target. Немедленные контрольные точки выполняются без таких задержек.'),
        ('option', 'Что хранит буфер в буферном кеше, кроме самой страницы данных?', 'Служебные сведения: файл и номер страницы в нём', 'Идентификатор файла и номер страницы в файле', 'По этим сведениям, например имени файла и положению страницы в нём, понятно, какая страница лежит в буфере.', NULL),
        ('option', 'Почему изменённая страница записывается на диск не сразу?', 'Чтобы реплики успели прочитать её из кеша', 'Чтобы реплики успели прочитать страницу из кеша', 'Реплики получают журнальные записи, а не страницы.', NULL),
        ('option', 'Почему изменённая страница записывается на диск не сразу?', 'Страницы ждут остановки сервера, чтобы записаться разом', 'Чтобы записать страницы разом при остановке сервера', 'Их записывают контрольные точки, фоновая запись и вытеснение.', 'Страницы записывают контрольные точки, фоновая запись и вытеснение, не дожидаясь остановки.'),
        ('option', 'Почему изменённая страница записывается на диск не сразу?', 'Её должна сначала проверить очистка на мёртвые версии', 'Чтобы очистка проверила страницу на мёртвые версии', 'Перед записью страницы на диск никакая проверка очисткой не требуется.', NULL),
        ('option', 'Почему изменённая страница записывается на диск не сразу?', 'Ради производительности: запись можно отложить', 'Чтобы объединять изменения и сокращать объём записи', 'Запись асинхронна и может откладываться, а надёжность при этом обеспечивает журнал.', 'Отложенная запись объединяет изменения и сокращает ввод-вывод, а надёжность при этом обеспечивает журнал.'),
        ('option', 'Почему запись через журнал эффективнее, чем запись каждой изменённой страницы сразу на диск?', 'Журнал не нужно сбрасывать на диск при фиксации', 'Запись WAL заменяет сохранение самих страниц', 'Наоборот, записи должны попасть на диск раньше изменённых данных.', 'Страницы данных тоже записываются на диск: при вытеснении, фоновой записи и контрольных точках. WAL позволяет отложить эту запись.'),
        ('option', 'Какие транзакции, изменявшие журналируемые данные, не будут считаться зафиксированными после аварийного восстановления? Двухфазная фиксация не используется.', 'Те, запись о фиксации которых не успела попасть в журнал', 'Те, чей COMMIT не успел сохраниться в WAL на диске', 'Работа остальных восстанавливается проигрыванием журнала.', 'Для восстановления фиксации нужна сохранившаяся запись COMMIT; запись только в потерянных буферах памяти недостаточна. Работа остальных восстанавливается проигрыванием журнала.'),
        ('option', 'Какие транзакции, изменявшие журналируемые данные, не будут считаться зафиксированными после аварийного восстановления? Двухфазная фиксация не используется.', 'Все, что были активны в момент контрольной точки', 'Те, что выполнялись в момент последней контрольной точки', 'Значение имеет только запись о фиксации в журнале.', 'Значение имеет сохранённая запись о фиксации в журнале, а не момент контрольной точки.'),
        ('option', 'Какие транзакции, изменявшие журналируемые данные, не будут считаться зафиксированными после аварийного восстановления? Двухфазная фиксация не используется.', 'Все, начатые после последней контрольной точки', 'Те, что начались после последней контрольной точки', 'Зафиксированные после неё восстанавливаются по журналу.', 'Зафиксированные после неё транзакции восстанавливаются по журналу.'),
        ('option', 'Какие транзакции, изменявшие журналируемые данные, не будут считаться зафиксированными после аварийного восстановления? Двухфазная фиксация не используется.', 'Никакие: восстановление доводит до конца все транзакции', 'Те, чьи страницы не успели записаться до сбоя', 'Незафиксированные к моменту сбоя транзакции обрываются.', 'Отсутствующие на диске изменения страниц восстанавливаются по сохранённому WAL; решающее значение имеет фиксация.'),
        ('option', 'Когда контрольная точка считается выполненной?', 'Когда записаны буферы, грязные на момент её начала', 'Когда данные сброшены и запись о ней сохранена в WAL', 'Тогда на диске гарантированно все изменения, сделанные до начала контрольной точки; более поздние изменения записывать к её завершению не требуется.', 'Должны быть надёжно сохранены данные и служебное состояние на момент её начала, запись контрольной точки в WAL и контрольная информация (pg_control). Последующие изменения могут оставаться в кеше.'),
        ('option', 'Что добавляет в журнал уровень replica по сравнению с minimal?', 'Данные для резервных копий и физической репликации', 'Данные для физических копий с WAL и репликации', 'На уровне minimal журнал обеспечивает только восстановление после сбоя.', 'На уровне minimal журнал обеспечивает только восстановление после сбоя; восстановление из базовой копии по WAL и физическая репликация требуют replica.'),
        ('option', 'Что делает сервер при остановке в режиме fast?', 'Сразу запускается снова с теми же настройками', 'Перечитывает настройки и возобновляет обслуживание', 'Это остановка, а не перезапуск.', 'Остановка fast не является перечитыванием конфигурации или возобновлением обслуживания.'),
        ('option', 'Что делает сервер при остановке в режиме fast?', 'Ждёт, пока все клиенты отключатся сами', 'Ждёт завершения сеансов и затем останавливается', 'Так работает режим smart.', NULL),
        ('option', 'Что делает сервер при остановке в режиме fast?', 'Обрывает соединения и выполняет контрольную точку', 'Отключает клиентов и выполняет контрольную точку', 'Обрывает открытые соединения и перед выключением выполняет контрольную точку, поэтому при следующем запуске сервер сразу готов к работе.', 'Отключает клиентов, отменяя их активные транзакции, и перед выключением выполняет контрольную точку, поэтому при следующем запуске сервер сразу готов к работе.'),
        ('option', 'Что делает сервер при остановке в режиме fast?', 'Выключается без контрольной точки', 'Прерывает процессы без завершающей контрольной точки', 'Это режим immediate.', NULL),
        ('option', 'Что произойдёт, если на сервере PostgreSQL установить fsync = off?', 'Журнал предзаписи перестанет записываться совсем', NULL, 'Журнал пишется по-прежнему, только без ожидания записи на диск.', 'WAL продолжает записываться, но PostgreSQL не обеспечивает его принудительный долговечный сброс.'),
        ('option', 'Что произойдёт, если на сервере PostgreSQL установить fsync = off?', 'Файлы данных будут сбрасываться вызовом fdatasync вместо fsync', NULL, 'Параметр fsync — выключатель всех сбросов, а не выбор вызова.', 'fsync управляет принудительной синхронизацией записи с устойчивым носителем; он не выбирает между fsync и fdatasync и не прекращает обычную запись файлов.'),
        ('option', 'Чем системный вызов fdatasync отличается от fsync?', 'fdatasync может не сбрасывать лишние метаданные файла', 'fdatasync не сбрасывает метаданные, не нужные для чтения', 'Например, время изменения файла, не нужное для чтения данных. Поэтому он может быть быстрее fsync; насколько — зависит от файловой системы и диска.', 'fdatasync синхронизирует данные и метаданные, необходимые для последующего чтения, например размер файла; время изменения файла синхронизировать не требуется. Поэтому он может быть быстрее fsync.'),
        ('option', 'Остальные настройки сохранности оставлены по умолчанию. Что верно при сравнении двух отдельных случаев: synchronous_commit = off (при fsync = on) и fsync = off?', 'При fsync = off после сбоя ОС или питания база может оказаться повреждённой', NULL, 'Нарушается порядок «сначала журнал, потом данные» на диске.', 'Нет гарантии порядка сохранения WAL и страниц на устойчивом носителе.'),
        ('option', 'Зачем нужен параметр full_page_writes = on?', 'Чтобы восстановить после сбоя частично записанную страницу', 'Чтобы восстановить страницу, записанную частично', 'Первое изменение страницы после контрольной точки записывает в журнал её полную копию. Атомарность записи целой страницы не гарантируется: при сбое питания может сохраниться лишь её часть.', NULL),
        ('option', 'Зачем нужен параметр full_page_writes = on?', 'Он включает запись полной копии страницы в журнал при каждом её изменении', 'Чтобы сохранять полный образ при каждом изменении', 'Полная копия нужна только при первом изменении страницы после контрольной точки; дальше пишутся обычные записи журнала.', 'Полный образ записывается при первом изменении страницы после контрольной точки, а не при каждом изменении.'),
        ('option', 'Зачем нужен параметр full_page_writes = on?', 'Он нужен для логической репликации и декодирования', 'Чтобы включить логическое декодирование журнала', 'Этот механизм нужен для восстановления страниц после сбоя.', NULL),
        ('option', 'Зачем нужен параметр full_page_writes = on?', 'Он заставляет записывать на диск все изменённые страницы при каждом COMMIT', 'Чтобы сбрасывать страницы данных при каждом COMMIT', 'COMMIT не требует сброса изменённых страниц данных; при обычной фиксации сервер ждёт сброса журнала. full_page_writes управляет записью полных копий страниц в журнал.', NULL),
        ('explanation', 'Что произойдёт, если на сервере PostgreSQL установить fsync = off?', NULL, NULL, 'Сбой самого PostgreSQL без сбоя ОС не опасен: данные остаются в кеше ядра. Опасен сбой ОС или питания. На рабочем сервере fsync всегда on: SHOW fsync;', 'Сбой самого PostgreSQL без сбоя ОС не опасен: данные остаются в кеше ядра. Опасен сбой ОС или питания. Для данных, сохранность которых необходима, fsync оставляют включённым. Проверка: SHOW fsync;')
    ) AS fixes(kind, question_text, opt_text, new_opt_text, old_text, new_text)
    LOOP
        -- Сначала ровно один вопрос по тексту (прежнему или новому), дальше всё только по его id.
        SELECT count(*), min(id) INTO matches, qid FROM questions
        WHERE question_text IN (fix.question_text, CASE WHEN fix.kind = 'question' THEN fix.new_text ELSE fix.question_text END);
        IF matches <> 1 THEN RAISE EXCEPTION 'Не найден единственный вопрос для исправления'; END IF;
        IF fix.kind = 'question' THEN
            UPDATE questions SET question_text = fix.new_text WHERE id = qid;
        ELSIF fix.kind = 'explanation' THEN
            PERFORM 1 FROM questions WHERE id = qid AND explanation IN (fix.old_text, fix.new_text);
            IF NOT FOUND THEN RAISE EXCEPTION 'Неожиданное пояснение вопроса'; END IF;
            UPDATE questions SET explanation = fix.new_text WHERE id = qid;
        ELSE
            SELECT count(*), min(o.key) INTO matches, k
            FROM questions q, jsonb_each_text(q.options) o
            WHERE q.id = qid AND o.value IN (fix.opt_text, coalesce(fix.new_opt_text, fix.opt_text));
            IF matches <> 1 THEN RAISE EXCEPTION 'Не найден единственный вариант ответа для исправления'; END IF;
            IF fix.new_text IS NOT NULL THEN
                PERFORM 1 FROM questions WHERE id = qid AND option_notes ->> k IN (fix.old_text, fix.new_text);
                IF NOT FOUND THEN RAISE EXCEPTION 'Неожиданное пояснение варианта'; END IF;
                UPDATE questions SET option_notes = jsonb_set(option_notes, ARRAY[k], to_jsonb(fix.new_text)) WHERE id = qid;
            END IF;
            IF fix.new_opt_text IS NOT NULL THEN
                UPDATE questions SET options = jsonb_set(options, ARRAY[k], to_jsonb(fix.new_opt_text)) WHERE id = qid;
            END IF;
        END IF;
    END LOOP;
END
$fix$;

COMMIT;
